// Country names and flags for every ISO country. Flags are static SVGs in /public/flags (Windows can't render flag
// emoji), so nothing is added to the JS bundle. List generated by scripts/gen-countries.ts.
import { ALL_COUNTRIES } from "@/lib/countries";
import { cn } from "@/lib/utils";

export const COUNTRIES = ALL_COUNTRIES;
const BY_CODE = new Map(ALL_COUNTRIES.map(([code, name]) => [code, name]));

export const countryName = (code: string | null | undefined) => (code ? BY_CODE.get(code.toUpperCase()) ?? code : null);

export function Flag({ code, className }: { code: string | null | undefined; className?: string }) {
  const c = code?.toUpperCase();
  if (!c || !BY_CODE.has(c)) return null;
  return (
    // eslint-disable-next-line @next/next/no-img-element -- tiny static SVGs; next/image adds nothing here
    <img
      src={`/flags/${c}.svg`}
      alt=""
      title={BY_CODE.get(c)}
      loading="lazy"
      className={cn("inline-block h-3.5 w-auto shrink-0 rounded-[2px] shadow-[0_0_0_1px_rgb(0_0_0/0.08)]", className)}
    />
  );
}

/** Flag + full country name, e.g. [flag] Finland. */
export function CountryLabel({ code, city, className }: { code: string | null | undefined; city?: string | null; className?: string }) {
  if (!code && !city) return null;
  return (
    <span className={cn("inline-flex items-center gap-1.5", className)}>
      <Flag code={code} />
      <span>{[city, countryName(code)].filter(Boolean).join(", ")}</span>
    </span>
  );
}
